0b6fb833-528c-49a5-878c-8124ff99e5b4.content:
PS C:\Windows\system32> Start-Process "ms-windows-store://"
PS C:\Windows\system32> Get-AppXPackage -AllUsers | Where-Object { $_.Name -like "*Microsoft.WindowsStore*" } | Foreach { Add-AppxPackage -DisableDevelopmentMode -Register "$($_.InstallLocation)\AppXManifest.xml" }
PS C:\Windows\system32> $store = Get-AppxPackage -AllUsers | Where-Object Name -eq "Microsoft.WindowsStore"
PS C:\Windows\system32> if ($store) {
>>     Write-Host " Store найден. Версия: $($store.Version)" -ForegroundColor Green
>>     Write-Host "   Состояние: $($store.Status) | Архитектура: $($store.Architecture)" -ForegroundColor Cyan
>>     if ($store.Status -ne "Ok") {
>>         Write-Host "  Пакет не в состоянии 'Ok'. Может потребоваться восстановление." -ForegroundColor Yellow
>>     }
>> } else {
>>     Write-Host " Store не обнаружен в AppX-пакетах!" -ForegroundColor Red
>> }
 Store не обнаружен в AppX-пакетах!
PS C:\Windows\system32>

